    let mut max_cost = pen_cost;
    let mut max_item = "pen";

    if pad_cost > max_cost {
        max_cost = pad_cost;
        max_item = "pad";
    }

    if ink_cost > max_cost {
        max_cost = ink_cost;
        max_item = "ink";
    }

    println!("Item with the highest cost: {}", max_item);
}

